name: PR Title Validation

on:
  pull_request_target:
    types: [opened, synchronize, reopened, edited]
    branches:
      - master
      - '[0-9]+.[0-9]+.x'

permissions:
  pull-requests: write
  contents: read

jobs:
  validate-pr-title:
    runs-on: ubuntu-latest
    steps:
      - name: Validate PR Title
        id: validate
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { execSync } = require('child_process');

            // Get PR information from environment variables
            const prTitle = process.env.PR_TITLE || '';
            const prBody = process.env.PR_BODY || '';

            // Write PR data to temporary file (secure approach)
            const fs = require('fs');
            const tempDir = '/tmp/pr-validation';
            fs.mkdirSync(tempDir, { recursive: true });

            // Create JSON file with PR data
            const prData = {
              title: prTitle,
              body: prBody
            };

            const tempFile = `${tempDir}/pr-data.json`;
            fs.writeFileSync(tempFile, JSON.stringify(prData));

            try {
              // Execute the secure JavaScript validation
              const result = execSync(`node ./scripts/validate-pr-title.js`, {
                cwd: process.env.GITHUB_WORKSPACE,
                encoding: 'utf8'
              });

              // Clean up
              fs.unlinkSync(tempFile);

              if (result.trim() === 'valid') {
                console.log('✅ PR title is valid');
              } else {
                console.log('❌ PR title validation failed');
                core.setFailed('PR title does not match conventional commit format');
              }
            } catch (error) {
              // Clean up on error
              if (fs.existsSync(tempFile)) {
                fs.unlinkSync(tempFile);
              }
              console.error('Validation error:', error.message);
              core.setFailed('PR title validation failed');
            }
        env:
          PR_TITLE: ${{ github.event.pull_request.title }}
          PR_BODY: ${{ github.event.pull_request.body }}
